def calculate_cost_n4():
    # Matches are: (1,2), (1,3), (1,4), (2,3), (2,4), (3,4)
    # Schedule:
    # Day 1: (2,3)
    # Day 2: (2,4)
    # Day 3: (3,4)
    # Day 4: (1,2)
    # Day 5: (1,3)
    # Day 6: (1,4)

    matches_day = {
        1: [(2, 3)],
        2: [(2, 4)],
        3: [(3, 4)],
        4: [(1, 2)],
        5: [(1, 3)],
        6: [(1, 4)]
    }

    player_first_day = {}
    player_last_day = {}

    for day, matches in matches_day.items():
        for p1, p2 in matches:
            for p in [p1, p2]:
                if p not in player_first_day:
                    player_first_day[p] = day
                player_last_day[p] = day

    total_cost = 0
    for p in range(1, 5):
        cost = player_last_day[p] - player_first_day[p] + 1
        total_cost += cost
        print(f"Player {p} cost: {cost}")

    print(f"Total cost N=4: {total_cost}")

calculate_cost_n4()
